#!/usr/bin/env python3
"""Freeze a pretrained sign-only Panoramax follow-up; launch is separately gated."""
import json,shutil,sys
from pathlib import Path
JOB=Path('/home/raphael/streetshots-d5-20261114');ROOT=JOB/'balanced-v1';sys.path.insert(0,str(JOB/'expanded-v1/recipe'))
from prepare_expanded_publication import sha,write,inventory

def main():
    check=json.loads((ROOT/'panoramax-head-check.json').read_text());assert check['sign_channel_preserved'] and not check['training_started']
    data=json.loads((JOB/'publication-receipts/d9-balanced-dataset.json').read_text());assert data['postverification'] and data['private']
    definition={'schema':'streetshots-panoramax-sign-finetune-v1','candidate':'d10','initialization':'Pretrained Panoramax YOLO11l; retain learned box regression and sign class0, remove face/plate output channels. Do not start from scratch.','source_repository':'Panoramax/detect_face_plate_sign','source_revision':'de311725ddae469c200cce0f86126fd4c043f24b','source_checkpoint':'yolo11l_panoramax.pt','source_sha256':check['source_sha256'],'head_transfer_verification':check,'dataset_revision':data['revision'],'dataset_manifest_sha256':sha(ROOT/'data/corrected-sources.json'),'views_sha256':sha(ROOT/'data/views.json'),'schedule_sha256':sha(ROOT/'data/schedules.json'),'training_recipe_sha256':sha(ROOT/'recipe/train_balanced.py'),'epochs':20,'draws_per_epoch':1024,'epoch_semantics':'1024 balanced draws, not a full-source pass; first20 frozen d9 mixed schedules','batch':4,'nominal_batch_size':16,'optimizer':'AdamW','lr0':.0001,'warmup_epochs':2,'imgsz':1024,'amp':True,'augmentation':'Same HSV-only recipe as d9','frozen_layers':None,'seed':14,'selection':'Same development-phone policy: max recall at <=4 mean proposals/image, then precision,higher threshold,earlier epoch; epoch0 eligible','validation_images':17,'validation_references':33,'mapillary_sample_usage':'Excluded from training and checkpoint/threshold selection; automatic benchmark is diagnostic only','consumed_holdout_usage':False,'role':'Larger offline teacher experiment, no phone deployment','budget_comparison':'Different architecture and batch/accumulation from d9; not an equal-compute comparison. Actual optimizer calls and updates logged.','launch_gate':'Only after d9 comparison and epoch logs are verified on private HF, and GPU0 Mapillary benchmark completes.','scripts':{name:sha(ROOT/'recipe'/name) for name in ['train_balanced.py','train_latest.py','train_evaluate.py','mobile_replay.py','balanced_views.py']}}
    write(ROOT/'panoramax-definition.json',definition);publication=ROOT/'publication';target=publication/'detector/d10/definition';target.mkdir(parents=True,exist_ok=False)
    shutil.copy2(ROOT/'panoramax-definition.json',target/'definition.json');shutil.copy2(ROOT/'panoramax-head-check.json',target/'head-transfer-check.json');(target/'recipe').mkdir()
    for name in definition['scripts']:shutil.copy2(ROOT/'recipe'/name,target/'recipe'/name)
    (target/'README.md').write_text('# Panoramax sign-only fine-tuning experiment (d10)\n\nStart from the published Panoramax YOLO11l weights, preserving the learned sign class and box head. Face/plate outputs are removed; a CPU numerical check confirms the sign outputs match the original checkpoint before fine-tuning. No random restart.\n\nThe experiment uses20 epochs of1024 scheduled balanced draws from the corrected d9 source pool, batch4 with nominal batch16,1024px AMP, AdamW1e-4. These are sampling epochs, not20 full-source passes. Most labels remain weak. The larger architecture is intended for an offline teacher; no phone deployment is implied.\n\nSelection uses only the existing17-image development set and the frozen phone-pipeline recall budget. Epoch0 is eligible, so training need not replace a stronger original. The Mapillary automatic-reference sample and consumed geographic audit are excluded from model/threshold selection.\n\nTraining is gated on publication of the completed d9 comparison and epoch logs and completion of the separate GPU0 Mapillary benchmark. This definition does not claim training has started or improved anything.\n')
    inventory(publication,target,'model','detector/d10/definition/definition.json',ROOT/'panoramax-definition-inventory.json')
if __name__=='__main__':main()
